import java.util.*;

class MKAverage {
  private final int m, k;
  private final Deque<Integer> queue = new ArrayDeque<>();
  private final TreeMap<Integer, Integer> low = new TreeMap<>(),
      mid = new TreeMap<>(),
      high = new TreeMap<>();
  private int lowSize, highSize;
  private long midSum;

  public MKAverage(int m, int k) {
    this.m = m;
    this.k = k;
  }

  public void addElement(int num) {
    queue.addLast(num);
    insert(num);
    if (queue.size() > m) remove(queue.removeFirst());
  }

  public int calculateMKAverage() {
    return queue.size() < m ? -1 : (int) (midSum / (m - 2 * k));
  }

  // a value goes into the bucket whose range covers it, so low <= mid <= high holds at all times
  private void insert(int x) {
    if (lowSize > 0 && x <= low.lastKey()) {
      add(low, x);
      lowSize++;
    } else if (highSize > 0 && x >= high.firstKey()) {
      add(high, x);
      highSize++;
    } else {
      add(mid, x);
      midSum += x;
    }
    rebalance();
  }

  private void remove(int x) {
    if (lowSize > 0 && x <= low.lastKey()) {
      take(low, x);
      lowSize--;
    } else if (highSize > 0 && x >= high.firstKey()) {
      take(high, x);
      highSize--;
    } else {
      take(mid, x);
      midSum -= x;
    }
    rebalance();
  }

  // moves only boundary values between neighbouring buckets until low and high hold k values each
  private void rebalance() {
    while (lowSize > k) {
      int x = low.lastKey();
      take(low, x);
      lowSize--;
      add(mid, x);
      midSum += x;
    }
    while (highSize > k) {
      int x = high.firstKey();
      take(high, x);
      highSize--;
      add(mid, x);
      midSum += x;
    }
    while (lowSize < k && !mid.isEmpty()) {
      int x = mid.firstKey();
      take(mid, x);
      midSum -= x;
      add(low, x);
      lowSize++;
    }
    while (highSize < k && !mid.isEmpty()) {
      int x = mid.lastKey();
      take(mid, x);
      midSum -= x;
      add(high, x);
      highSize++;
    }
  }

  private void add(TreeMap<Integer, Integer> map, int x) {
    map.merge(x, 1, Integer::sum);
  }

  private void take(TreeMap<Integer, Integer> map, int x) {
    int c = map.get(x);
    if (c == 1) map.remove(x);
    else map.put(x, c - 1);
  }
}
